import type { FighterId } from './game/types';
import { phone } from './input/device';

export interface FighterDefinition {
  name:string; series:string; color:string; outlineWidth:number; moves:string[]; model:string; portrait:string;
  formModel?:string;
  clips?:string[];
  /** Clip name patterns for rush stages 1..RUSH_STAGES-1 (stage 0 is the
   *  light's own clip), resolved like `clips` against the body's clips and,
   *  when `rushModel` is set, the clips it carries. */
  rushClips?:string[];
  /** Animation-only GLB with the rush clips, bound by bone name onto the
   *  fighter's own skeleton, so the shipped body's bytes stay untouched. */
  rushModel?:string;
  /** Round 3: animation-only GLBs whose clips join the body's own, bound by
   *  bone name like `rushModel`, so a stream can add or replace clips without
   *  rewriting the shipped body (a clip with a name the body already has
   *  replaces it). The idle's own clip file is `IdleProfile.model` instead. */
  extraModels?:string[];
  /** Round 5 (GUMMY): animation-only GLBs whose clips join the awakened form's own (`formModel`), bound by bone name
   *  onto the form's skeleton as `extraModels` are onto the body's - a clip with a name the form already has replaces
   *  it. Loaded with the fighter, per room. */
  formExtraModels?:string[];
  /** A form that is another body with a kit of its own (Hawser's YUGE, 13 October 2026): the four slots' clips
   *  and the root caps of the form's body, where they are not the fighter's own (`clips`, `rootMotion`), and its four
   *  moves' labels on the HUD's cards (`formShortMoves`; their names are AWAKENED_MOVES', game/awakening.ts). A form
   *  without them throws its fighter's clips by the same names, as every other form does. */
  formClips?:string[];
  formRootMotion?:{rise:number;drop:number;travel:number};
  formShortMoves?:string[];
  /** Round 5 (GUMMY): a mesh-only GLB of open hands (scripts/gummy/build_r5_hands.py) the renderer swaps in for the
   *  body's and the form's closed fists where a blow is thrown with the palms (src/render/gummy/openHands.ts). */
  openHandsModel?:string;
  shortMoves?:string[];
  normalization?:{scale:number;position:[number,number,number]};
  /** Explicit authored form origin/scale; otherwise normalize to fighter height. */
  formNormalization?:{scale:number;position:[number,number,number]};
  /** Metres from sole to crown, for the fighters who are normalised to a height.
   *  Set per fighter so the roster stands next to each other at fixed
   *  heights: KoKo 1.95, Kenzo/Nigo/Shirokane
   *  1.81, Kosho 1.80, Taisei 1.75, Gummy 1.74, Shiden 1.68, Konta 1.66,
   *  Ouga 1.64. A fighter with a `normalization` block keeps its
   *  authored origin and its scale is multiplied onto the same figures.
   *  Kosho's feet are not planted during his attacks (his legs are his
   *  weapon), which is what let him stand at full height: pinned, his heavy's lunge
   *  re-planted the ankle mid-kick from 1.78 m up.
   *  rather than pinned to their source scale. Defaults to 1.7, which is the
   *  roster's baseline; Taisei is 1.8 and has always been. */
  height?:number;
  /** Soft caps, in metres, on how far an attack's root may leave the rest pose.
   *  Only the replacement rigs need this: their clips carry the whole move on
   *  the root. Taisei and Konta were authored against measured contact points
   *  and must not be shifted. */
  rootMotion?:{rise:number;drop:number;travel:number};
}
