export type CameraMode='arena'|'dynamic'|'lockon'|'free'|'smart';
export const CAMERA_MODES:readonly CameraMode[]=['arena','dynamic','lockon','free','smart'];
export const CAMERA_VERSION=4;
export const ANIM_VERSION=2;
/** A save from before this version holding 'inked' (the default before Halo) is moved to Halo once; a save at this
 *  version keeps whatever it says. */
export const HUD_VERSION=2;
/** Round 4b (TARGETING): how a locked target is marked. 'glow' (the default)
 *  lights the target's whole silhouette in its threat colour - yellow idle,
 *  orange on a blockable attack, red on one that must be dodged
 *  (src/render/ThreatOutline.ts); 'brackets' is round 4's corner brackets,
 *  kept so the two can be compared. */
export type LockStyle='glow'|'brackets';
export type CameraStyle='close'|'classic'|'chase';
export const CAMERA_STYLES:readonly CameraStyle[]=['classic','close','chase'];
export const VFX_LEVELS=['full','reduced','minimal'] as const;
export type VfxLevel=typeof VFX_LEVELS[number];
/** The level's particle density (Settings.effects, 0.3-1, what every effect's counts are scaled by). */
export const VFX_DENSITY:Readonly<Record<VfxLevel,number>>={full:1,reduced:.65,minimal:.4};
/** What both menus offer, the default first; the third word is the note in the open list. */
/** The level a player who has not chosen one starts on: Full, the game as it was; Reduced on a phone (the phone pass,
 *  November 2026: on a small screen the full-screen impact frames and the colour fringe cover the fight, and the fewer
 *  particles are frame time and heat a phone does not have). A saved level, or a saved density, wins. */
export const defaultVfx=(small=phone()):VfxLevel=>small?'reduced':'full';
export const VFX_OPTIONS:readonly (readonly [VfxLevel,string,string?])[]=defaultVfx()==='reduced'
  ?[['full','Full','Richest'],['reduced','Reduced','Default'],['minimal','Minimal','Calmest']]
  :[['full','Full','Default'],['reduced','Reduced','Calmer'],['minimal','Minimal','Calmest']];
/** A save from before the level (an EFFECT DENSITY slider value, 0.3-1) as the level nearest it, so a player who turned
 *  the effects down keeps them down: 0.85 and up Full, from 0.5 Reduced, under it Minimal. */
export const vfxFromDensity=(density:number):VfxLevel=>density>=.85?'full':density>=.5?'reduced':'minimal';
export interface Settings { sensitivity:number; shake:number; effects:number; vfx:VfxLevel; volume:number; sfxVolume:number; voiceVolume:number; musicVolume:number; musicEnabled:boolean; homeAnimations?:boolean; audioMixVersion:number; quality:'high'|'medium'|'low'; cameraMode:CameraMode; cameraStyle:CameraStyle; cameraVersion:number; cinematics:boolean; lockStyle:LockStyle;
  /** The player picked the quality themselves. Until then it is the machine's (render/qualityTier.ts): picked from the
   *  GPU at boot and stepped down in a fight that cannot hold its frame rate. A save holding the old default 'high'
   *  without this is not a choice. */
  qualityChosen?:boolean;
  powerMode?:'auto'|'cool'|'full';
  animStyle:'twos'|'snap'|'classic';
  /** The animation default the save was written under (ANIM_VERSION). */
  animVersion?:number;
  /** How hard a controller rumbles, 0-1. */
  vibration:number;
  hudSkin:HudSkin;
  hudVersion?:number;
  moveLayout:MoveLayout;
  errorReports?:boolean; }
/** Every move-card layout (Settings.moveLayout), the default first; the third word is the note in the open list. */
export const MOVE_LAYOUTS=['row','pad'] as const;
export type MoveLayout=typeof MOVE_LAYOUTS[number];
export const MOVE_LAYOUT_OPTIONS:readonly (readonly [MoveLayout,string,string?])[]=[['row','Row','Recommended'],['pad','Pocket pad']];
export const HUD_SKINS=['halo','inked'] as const;
export type HudSkin=typeof HUD_SKINS[number];
/** The HUD looks a menu offers (Settings.hudSkin), the default first. */
export const HUD_SKIN_OPTIONS:readonly (readonly [HudSkin,string])[]=[['halo','Halo'],['inked','Inked']];
/** The graphics quality's choices, for every menu that offers them: AUTO is the machine's own (qualityTier.ts). */
export const QUALITY_OPTIONS:readonly (readonly ['auto'|Settings['quality'],string])[]=[['auto','AUTO'],['high','HIGH'],['medium','MEDIUM'],['low','LOW']];
/** What a quality menu shows: AUTO until the player has chosen. */
export const qualityChoice=(settings:Pick<Settings,'quality'|'qualityChosen'>)=>settings.qualityChosen?settings.quality:'auto';
/** A quality picked in a menu: a preset is the player's choice from then on; AUTO hands it back to the machine, starting
 *  from `machine` (qualityTier.ts autoQuality). */
export function chooseQuality(settings:Settings,value:string,machine?:Settings['quality']){
  if(value==='high'||value==='medium'||value==='low'){settings.quality=value;settings.qualityChosen=true;}
  else if(value==='auto'){settings.qualityChosen=false;if(machine)settings.quality=machine;}
}
export function loadSettings():Settings {
  const vfx=defaultVfx();
  const defaults:Settings={sensitivity:1,shake:.5,effects:VFX_DENSITY[vfx],vfx,volume:.7,sfxVolume:.85,voiceVolume:1,musicVolume:.75,musicEnabled:true,homeAnimations:true,audioMixVersion:3,quality:'high',powerMode:'auto',cameraMode:'dynamic',cameraStyle:'classic',cameraVersion:CAMERA_VERSION,cinematics:true,lockStyle:'glow',vibration:1,animStyle:'snap',animVersion:ANIM_VERSION,hudSkin:'halo',hudVersion:HUD_VERSION,moveLayout:'row',errorReports:true};
  try {
    const saved=JSON.parse(localStorage.getItem('rift-settings')||'{}');
    if(!saved||typeof saved!=='object')return defaults;
    for(const key of ['shake','volume','sfxVolume','voiceVolume','musicVolume','vibration'] as const)if(Number.isFinite(saved[key]))defaults[key]=Math.max(0,Math.min(1,saved[key]));
    if(saved.audioMixVersion!==3&&Number.isFinite(saved.musicVolume)&&saved.musicVolume>0)defaults.musicVolume=Math.min(1,saved.musicVolume*2.5);
    if(Number.isFinite(saved.sensitivity))defaults.sensitivity=Math.max(.3,Math.min(2,saved.sensitivity));
    if(['high','medium','low'].includes(saved.quality))defaults.quality=saved.quality;
    defaults.qualityChosen=saved.qualityChosen===true;
    defaults.powerMode=['auto','cool','full'].includes(saved.powerMode)?saved.powerMode:'auto';
    if(typeof saved.musicEnabled==='boolean')defaults.musicEnabled=saved.musicEnabled;
    if(typeof saved.homeAnimations==='boolean')defaults.homeAnimations=saved.homeAnimations;
    if(typeof saved.errorReports==='boolean')defaults.errorReports=saved.errorReports;
    if((CAMERA_MODES as readonly string[]).includes(saved.cameraMode))defaults.cameraMode=saved.cameraMode;
    // (A save from before version 2 holding 'lockon', or from before version 4 holding 'arena': the default of its day.)
    const olderCamera=saved.cameraVersion!==CAMERA_VERSION;
    if(olderCamera&&(saved.cameraMode==='arena'||(saved.cameraMode==='lockon'&&!(saved.cameraVersion>=2))))defaults.cameraMode='dynamic';
    if(saved.cameraStyle==='sparking')defaults.cameraStyle='close';   // the preview's name for it
    else if((CAMERA_STYLES as readonly string[]).includes(saved.cameraStyle))defaults.cameraStyle=saved.cameraStyle;
    // (The look 'close' from before version 4 was the default of its day too: Classic once, then whatever is chosen.)
    if(olderCamera&&defaults.cameraStyle==='close')defaults.cameraStyle='classic';
    if(typeof saved.cinematics==='boolean')defaults.cinematics=saved.cinematics;
    if(saved.lockStyle==='glow'||saved.lockStyle==='brackets')defaults.lockStyle=saved.lockStyle;
    // (A save from before ANIM_VERSION holding 'twos', the default of its day, is moved to Anime (smooth) once.)
    if((saved.animStyle==='twos'&&saved.animVersion===ANIM_VERSION)||saved.animStyle==='snap'||saved.animStyle==='classic')defaults.animStyle=saved.animStyle;
    // (A save from before HUD_VERSION holding 'inked', the default of its day, is moved to Halo once.)
    if((HUD_SKINS as readonly string[]).includes(saved.hudSkin)&&(saved.hudSkin!=='inked'||saved.hudVersion===HUD_VERSION))defaults.hudSkin=saved.hudSkin;
    if((MOVE_LAYOUTS as readonly string[]).includes(saved.moveLayout))defaults.moveLayout=saved.moveLayout;
    // VISUAL EFFECTS: the saved level, else the level nearest a saved density (the slider it replaced); the density is
    // the level's either way.
    defaults.vfx=(VFX_LEVELS as readonly string[]).includes(saved.vfx)?saved.vfx:Number.isFinite(saved.effects)?vfxFromDensity(saved.effects):vfx;
    defaults.effects=VFX_DENSITY[defaults.vfx];
    return defaults;
  }catch{return defaults;}
}
